bounded_host_request.command:
set -euo pipefail
docker exec -i gace-createvdobot-videobot-poll-1 node --input-type=module - <<'NODE'
import pg from 'pg';import{readFileSync}from'node:fs';
const e=process.env;const pool=new pg.Pool({host:e.VIDEOBOT_DB_HOST,database:e.VIDEOBOT_DB_NAME,user:e.VIDEOBOT_DB_USER,password:readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),max:1});
try{
 const r=await pool.query("SELECT s.state,s.screen_message_id FROM videobot_sticker_products p LEFT JOIN videobot_creator_sessions s ON s.owner_user_id=p.seller_user_id WHERE p.product_id=$1",['sp_76f23430d1c29ca355960a95']);
 if(r.rowCount!==1){process.exitCode=78;}
 else{
  const d=r.rows[0].state||{},screen=d.screen||'NONE',mid=r.rows[0].screen_message_id;
  console.log('STK_SELLER_SCREEN_CATEGORY='+(['sticker_choose','sticker_reconcile','sticker_edit_reconcile','home','sticker_sale_offer'].includes(screen)?screen:'OTHER'));
  console.log('STK_SELLER_PENDING_REGISTRATION='+Boolean(d.stickerPending));
  console.log('STK_SELLER_PENDING_EDIT='+Boolean(d.stickerEditPending));
  console.log('STK_SELLER_SCREEN_MESSAGE='+Boolean(mid));
  process.exitCode=d.stickerEditPending?71:d.stickerPending?.status==='needs_reconcile'?72:!mid?73:screen==='sticker_choose'?74:0;
 }
}finally{await pool.end();}
NODE
